package com.example.e_hospital.management.prototype.controller;

import com.example.e_hospital.management.prototype.service.HospitalService;
import jakarta.servlet.http.HttpSession;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;

@Controller
public class CareController {
    private static final List<String> CLINICAL=List.of("Doctor","Nurse","Administrator","Hospital Administrator"),FLOW=List.of("Doctor","Nurse","Receptionist","Administrator","Hospital Administrator"),
        QUEUE=List.of("Doctor","Nurse","Receptionist","Administrator","Hospital Administrator","Laboratory Staff","Pharmacist","Cashier");
    private final HospitalService service;private final String telegramBotToken;private final com.example.e_hospital.management.prototype.service.TelegramAccessService telegram;
    public CareController(HospitalService service,@org.springframework.beans.factory.annotation.Value("${careplus.telegram.bot-token:}") String telegramBotToken,com.example.e_hospital.management.prototype.service.TelegramAccessService telegram){this.service=service;this.telegramBotToken=telegramBotToken;this.telegram=telegram;}
    /** Demo doctor identity, or the linked staff identity after Telegram sign-in. */
    static String doctorIdentity(HttpSession s){return Objects.toString(s.getAttribute("demoDoctor"),"DOC-0001");}
    private String actor(HttpSession s){return String.valueOf(s.getAttribute("demoUser"));}
    private void allow(HttpSession s,List<String> roles,String message){if(!roles.contains(role(s)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,message);}
    /** In integration mode the Mini Apps require a Telegram-verified, linked session; synthetic logins are refused. */
    private void miniAccess(HttpSession s){if(telegram.integration()&&!"telegram".equals(s.getAttribute("authSource")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Open CarePlus from Telegram and link your hospital account.");}
    private String patientIdentity(HttpSession s){return Objects.toString(s.getAttribute("demoPatient"),"PAT-0001");}
    private String role(HttpSession s){return String.valueOf(s.getAttribute("demoRole"));}
    private void staff(HttpSession s){if(role(s).equals("Patient"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Use the patient Mini App.");}
    private void clinician(HttpSession s){if(!List.of("Doctor","Administrator","Hospital Administrator").contains(role(s)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"A clinician must review this action.");}
    private void scope(HttpSession s,String patient,String encounter){staff(s);if(role(s).equals("Doctor")&&!encounter.isBlank()&&!service.get("visits",encounter).get("doctor").equals(doctorIdentity(s)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This visit is assigned to another demo doctor.");}
    @GetMapping({"/care/patients/{patient}","/care/patients/{patient}/encounters/{encounter}"}) String workspace(@PathVariable String patient,@PathVariable(required=false)String encounter,HttpSession s,Model m){scope(s,patient,encounter==null?"":encounter);if(!List.of("Doctor","Nurse","Administrator","Hospital Administrator").contains(role(s)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Use the administrative appointment and queue views.");service.careContext(patient,encounter==null?"":encounter);m.addAttribute("patientId",patient);m.addAttribute("encounterId",encounter==null?"":encounter);m.addAttribute("role",role(s));return "ui/care";}
    @GetMapping({"/mini/doctor","/mini/patient"}) String portal(jakarta.servlet.http.HttpServletRequest req,HttpSession s,Model m){String mode=req.getRequestURI().endsWith("patient")?"patient":"doctor";if(mode.equals("patient")&&!role(s).equals("Patient"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Sign in as the synthetic patient to preview this page.");if(!mode.equals("patient"))staff(s);miniAccess(s);
        m.addAttribute("mode",mode);m.addAttribute("role",role(s));m.addAttribute("doctorId",doctorIdentity(s));m.addAttribute("authSource",Objects.toString(s.getAttribute("authSource"),"demo"));m.addAttribute("appMode",telegram.integration()?"integration":"demo");return "ui/mini";}
    @GetMapping("/care/queue") String queue(HttpSession s,Model m){allow(s,QUEUE,"Queue management is unavailable for this role.");m.addAttribute("role",role(s));m.addAttribute("doctorId",doctorIdentity(s));return "ui/queue";}
    @GetMapping("/care/appointments/{id}") String appointment(@PathVariable String id,HttpSession s,Model m){staff(s);service.journey(id);m.addAttribute("appointmentId",id);m.addAttribute("role",role(s));m.addAttribute("doctorId",doctorIdentity(s));return "ui/appointment";}
    @GetMapping("/care/checkin") String checkinDesk(HttpSession s,Model m){allow(s,List.of("Receptionist","Nurse","Administrator","Hospital Administrator"),"Check-in desk is for reception and nursing staff.");m.addAttribute("role",role(s));return "ui/checkin";}
    @GetMapping("/api/care/journey") @ResponseBody Object journey(@RequestParam String id,HttpSession s){
        var j=service.journey(id);@SuppressWarnings("unchecked") var p=(Map<String,String>)j.get("patient");
        if(role(s).equals("Patient")&&!p.get("id").equals(patientIdentity(s)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Appointment unavailable.");
        if(!List.of("Patient").contains(role(s))&&!FLOW.contains(role(s))&&!List.of("Laboratory Staff","Pharmacist","Cashier").contains(role(s)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Journey unavailable for this role.");
        if(!CLINICAL.contains(role(s))){var copy=new LinkedHashMap<>(j);var patient=new LinkedHashMap<>(p);for(String k:List.of("allergies","conditions","address","email","emergencyContact","emergencyPhone"))patient.remove(k);copy.put("patient",patient);return copy;}
        return j;
    }
    @PostMapping("/api/care/queue/call-next") @ResponseBody Object callNext(@RequestBody Map<String,String> b,HttpSession s){allow(s,QUEUE,"This role cannot call patients.");String doctor=role(s).equals("Doctor")?doctorIdentity(s):Objects.toString(b.get("doctor"),"");return service.callNext(doctor,b.getOrDefault("station","Consultation"),actor(s));}
    @PostMapping("/api/care/checkin/scan") @ResponseBody Object scan(@RequestBody Map<String,String> b,HttpSession s){allow(s,List.of("Receptionist","Nurse","Administrator","Hospital Administrator"),"Check-in desk is for reception and nursing staff.");return service.redeemCheckInTicket(b.get("code"),actor(s));}
    @GetMapping("/api/care/checkin/history") @ResponseBody Object history(@RequestParam(defaultValue="")String id,HttpSession s){allow(s,FLOW,"Check-in history is unavailable for this role.");return service.checkInHistory(id);}
    @GetMapping("/api/care/arrival") @ResponseBody Object arrival(HttpSession s){allow(s,List.of("Receptionist","Administrator","Hospital Administrator"),"Only reception can display the arrival code.");return service.arrivalCode(false);}
    @PostMapping("/api/care/arrival/rotate") @ResponseBody Object rotate(HttpSession s){allow(s,List.of("Receptionist","Administrator","Hospital Administrator"),"Only reception can rotate the arrival code.");return service.arrivalCode(true);}
    @PostMapping("/api/care/arrival-checkin") @ResponseBody Object arrivalCheckin(@RequestBody Map<String,String> b,HttpSession s){if(!role(s).equals("Patient"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Patient Mini App only.");miniAccess(s);return service.arrivalCheckIn(patientIdentity(s),b.get("appointment"),b.get("code"),actor(s));}
    @GetMapping("/api/care/context") @ResponseBody Object context(@RequestParam String patient,@RequestParam(defaultValue="")String encounter,HttpSession s){scope(s,patient,encounter);if(!List.of("Doctor","Nurse","Administrator","Hospital Administrator").contains(role(s)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Clinical chart access is unavailable for this role.");return service.careContext(patient,encounter);}
    @PostMapping("/api/care/action") @ResponseBody Object action(@RequestBody Map<String,String> b,HttpSession s){String action=b.getOrDefault("action","");String p=b.getOrDefault("patient",""),e=b.getOrDefault("encounter","");scope(s,p,e);
        if(action.equals("queue")&&List.of("Laboratory Staff","Pharmacist","Cashier").contains(role(s))){var q=service.get("queues",b.getOrDefault("queue",""));if(List.of("Registration","Triage","Consultation","Doctor review").contains(q.getOrDefault("station","Consultation"))||"Transferred".equals(b.get("status")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can update your own department queue only.");}
        else if(List.of("triage","queue","checkin").contains(action)){if(!List.of("Doctor","Nurse","Receptionist","Administrator","Hospital Administrator").contains(role(s)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This role cannot change patient flow.");if(role(s).equals("Receptionist")&&action.equals("triage"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Nursing review is required.");}else clinician(s);
        return service.careAction(p,e,action,b,String.valueOf(s.getAttribute("demoUser")));
    }
    @GetMapping("/api/care/mobile") @ResponseBody Object mobile(HttpSession s){
        if(List.of("Laboratory Staff","Pharmacist","Cashier").contains(role(s))){var all=service.mobileContext("Administrator",doctorIdentity(s));var out=new LinkedHashMap<String,Object>();out.put("queues",all.get("queues"));out.put("doctors",all.get("doctors"));out.put("departments",all.get("departments"));for(String k:List.of("appointments","visits","laboratory","imaging","documents"))out.put(k,List.of());return out;}
        if(!List.of("Doctor","Patient","Administrator","Hospital Administrator","Nurse","Receptionist").contains(role(s)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This preview is unavailable for your role.");var data=new LinkedHashMap<>(service.mobileContext(role(s),role(s).equals("Patient")?patientIdentity(s):doctorIdentity(s)));if(role(s).equals("Receptionist")){data.put("documents",List.of());data.put("laboratory",List.of());data.put("imaging",List.of());@SuppressWarnings("unchecked") var visits=(List<Map<String,String>>)data.get("visits");data.put("visits",visits.stream().map(v->{var copy=new LinkedHashMap<>(v);copy.remove("notes");copy.remove("dischargePlan");return copy;}).toList());}return data;}
    @GetMapping("/api/care/slots") @ResponseBody Object slots(@RequestParam String doctor,@RequestParam String date){return service.availableSlots(doctor,date);}
    @PostMapping("/api/care/booking") @ResponseBody Object booking(@RequestBody Map<String,String> b,HttpSession s){if(!role(s).equals("Patient"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Use the appointment module.");if(!service.availableSlots(b.get("doctor"),b.get("date")).contains(b.get("time")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an available appointment slot.");var v=new LinkedHashMap<>(b);v.put("patient",patientIdentity(s));v.put("name","Patient Mini App booking");v.put("type","Consultation");return service.save("appointments",null,v,actor(s));}
    @PostMapping("/api/care/patient-appointment") @ResponseBody Object patientAppointment(@RequestBody Map<String,String> b,HttpSession s){if(!role(s).equals("Patient"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Patient preview only.");var a=service.get("appointments",b.get("appointment"));if(!a.get("patient").equals(patientIdentity(s)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Appointment unavailable.");String action=b.getOrDefault("action","");if(!List.of("Cancel","Reschedule").contains(action))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid appointment action.");if(a.containsKey("encounter"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Contact reception for a checked-in appointment.");return service.transition("appointments",a.get("id"),action,b,actor(s));}
    @PostMapping("/api/care/checkin") @ResponseBody Object token(@RequestBody Map<String,String>b,HttpSession s){if(!role(s).equals("Patient"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Patient preview only.");if(!"true".equals(b.get("verified")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Confirm your demo appointment identity.");
        // Presence must be proven: reception redeems the ticket, or the patient scans the hospital arrival code. A patient cannot redeem their own ticket.
        if(!b.getOrDefault("token","").isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Show this code to reception, or scan the hospital arrival QR to check yourself in.");return service.checkInToken(b.get("appointment"),patientIdentity(s),b.getOrDefault("token",""),actor(s));}
    /** Fails closed: without a configured bot token nothing is verified; with one, a valid signature still does not grant record access. */
    @PostMapping("/api/care/telegram/link") @ResponseBody Object telegram(@RequestBody(required=false) Map<String,String> b){
        if(telegramBotToken.isBlank())throw new ResponseStatusException(HttpStatus.NOT_IMPLEMENTED,"Live Telegram access is disabled. Server verification of initData and authenticated hospital account linking are required. Use the local synthetic preview.");
        try{new com.example.e_hospital.management.prototype.service.TelegramInitDataVerifier(telegramBotToken,java.time.Duration.ofHours(1),java.time.Clock.systemUTC()).verify(b==null?null:b.get("initData"));}
        catch(IllegalArgumentException ex){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,ex.getMessage());}
        throw new ResponseStatusException(HttpStatus.CONFLICT,"Telegram identity verified. Linking it to a hospital account requires authenticated hospital sign-in, which this prototype does not provide.");
    }
}
